const $=id=>document.getElementById(id),shell=document.querySelector('.app-shell'),draftKey='web-notes-ui-prototype-synthetic-v1';let stored;try{stored=JSON.parse(localStorage.getItem(draftKey)||'null')}catch{}let notes=stored?.notes??structuredClone(fixture),active='1',selected=new Set(),selecting=false,trash=stored?.trash??[],folderFilter='Tất cả ghi chú',inTrash=false,timer,saveState='synced',previewMode=null;
function esc(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function current(){return notes.find(n=>n.id===active)}
function render(){const q=$('search').value.toLocaleLowerCase('vi');const source=inTrash?trash:notes;const rows=(previewMode==='empty'?[]:source.filter(n=>(inTrash||folderFilter==='Tất cả ghi chú'||n.folder===folderFilter)&&`${n.title} ${n.text} ${n.folder}`.toLocaleLowerCase('vi').includes(q)));$('cards').replaceChildren(...rows.map(n=>{const b=document.createElement('button');b.type='button';b.className='note-card';b.dataset.id=n.id;b.setAttribute('aria-current',String(n.id===active));if(selecting)b.setAttribute('aria-pressed',String(selected.has(n.id)));b.innerHTML=`<strong>${esc(n.title||'Chưa có tiêu đề')}</strong><p>${esc(n.text)}</p><small>${esc(n.folder)} · ${esc(n.time)}</small>`;b.addEventListener('click',()=>selecting?toggleSelect(n.id):open(n.id));return b;}));if(!rows.length){const empty=document.createElement('p');empty.className='empty-state';empty.textContent=inTrash?'Thùng rác đang trống.':q?'Không tìm thấy ghi chú phù hợp.':'Chưa có ghi chú trong kho này.';$('cards').append(empty);}$('note-count').textContent=`${rows.length} ghi chú`;$('restore-trash').hidden=!inTrash||!trash.length;$('select-mode').hidden=inTrash;$('bulk').hidden=!selecting;$('selected-count').textContent=`${selected.size} đã chọn`;document.querySelectorAll('.folder[data-folder]').forEach(b=>b.classList.toggle('active',!inTrash&&b.dataset.folder===folderFilter));}
function setState(state,label){saveState=state;$('save-state').textContent=label;$('status-text').textContent=label;document.querySelector('.statusbar').dataset.state=state;}
function resizeTitle(){const el=$('title');el.style.height='auto';el.style.height=Math.min(el.scrollHeight,parseFloat(getComputedStyle(el).maxHeight)||el.scrollHeight)+'px';}
function persistFixture(){try{localStorage.setItem(draftKey,JSON.stringify({notes,trash}));return true}catch{return false}}
function open(id){active=id;const n=current();if(!n)return;shell.classList.add('editing');$('title').value=n.title;resizeTitle();$('body').value=n.text;$('folder-meta').textContent=n.folder||'Chưa phân loại';$('updated-meta').textContent='Vừa cập nhật';$('word-count').textContent=`${n.text.trim()?n.text.trim().split(/\s+/).length:0} từ`;setState('synced','Đã đồng bộ');render();}
function autosave(){const n=current();if(!n)return;n.title=$('title').value;n.text=$('body').value;resizeTitle();const held=persistFixture();setState(held?'local':'error',held?'Đã giữ trên máy · chưa đồng bộ':'Không lưu được fixture trên máy');$('word-count').textContent=`${n.text.trim()?n.text.trim().split(/\s+/).length:0} từ`;clearTimeout(timer);timer=setTimeout(()=>{setState('syncing','Đang đồng bộ');setTimeout(()=>{n.time='Vừa rồi';setState('synced','Đã đồng bộ');render();},240);},700);}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),1800);}
function toggleSelect(id){selected.has(id)?selected.delete(id):selected.add(id);render();}
function create(){const n={id:crypto.randomUUID(),title:'Ghi chú mới',folder:'',text:'',time:'Vừa rồi'};notes.unshift(n);active=n.id;render();open(n.id);$('title').focus();$('title').select();}
document.querySelectorAll('.folder[data-folder]').forEach(b=>{b.setAttribute('aria-label',b.dataset.folder);b.addEventListener('click',()=>{folderFilter=b.dataset.folder;$('folder-title').textContent=folderFilter;document.querySelector('.eyebrow').textContent='KHÔNG GIAN CÁ NHÂN';shell.classList.remove('show-folders');render();});});
document.querySelectorAll('[data-view]').forEach(b=>{b.setAttribute('aria-label',b.dataset.view==='trash'?'Thùng rác':'Code Inbox');b.addEventListener('click',()=>{shell.classList.remove('show-folders');if(b.dataset.view==='inbox'){toast('Code Inbox · fixture tổng hợp');return;}inTrash=true;$('folder-title').textContent='Thùng rác';render();});});
for(const id of ['new-note','new-note-mobile'])$(id).addEventListener('click',create);
$('show-folders').addEventListener('click',()=>shell.classList.toggle('show-folders'));
$('back-list').addEventListener('click',()=>shell.classList.remove('editing'));
$('search').addEventListener('input',render);$('nav-search').addEventListener('click',()=>{$('search').focus();shell.classList.remove('editing');});$('nav-notes').addEventListener('click',()=>shell.classList.remove('editing'));
$('title').addEventListener('input',autosave);$('body').addEventListener('input',autosave);
$('select-mode').addEventListener('click',()=>{selecting=!selecting;selected.clear();$('select-mode').setAttribute('aria-pressed',String(selecting));render();});$('cancel-select').addEventListener('click',()=>{selecting=false;selected.clear();$('select-mode').setAttribute('aria-pressed','false');render();});
$('bulk-move').addEventListener('click',()=>{for(const n of notes.filter(x=>selected.has(x.id)))n.folder='Cá nhân';toast('Đã chuyển vào Cá nhân (fixture)');selected.clear();selecting=false;render();});$('bulk-trash').addEventListener('click',()=>{trash.push(...notes.filter(n=>selected.has(n.id)));notes=notes.filter(n=>!selected.has(n.id));persistFixture();selected.clear();selecting=false;render();toast('Đã chuyển vào thùng rác (fixture)');});$('nav-trash').addEventListener('click',()=>{inTrash=true;$('folder-title').textContent='Thùng rác';shell.classList.remove('editing');render();});$('restore-trash').addEventListener('click',()=>{const n=trash.pop();if(n){notes.unshift(n);persistFixture();toast('Đã khôi phục ghi chú tổng hợp');}if(!trash.length)inTrash=false;render();});$('nav-inbox').addEventListener('click',()=>toast('Code Inbox · fixture tổng hợp'));
$('move-note').addEventListener('click',()=>{const n=current();n.folder=n.folder==='Công việc'?'Cá nhân':'Công việc';$('folder-meta').textContent=n.folder;render();toast(`Đã chuyển vào ${n.folder} (fixture)`);});$('trash-note').addEventListener('click',()=>{const n=current();trash.push(n);notes=notes.filter(x=>x.id!==active);persistFixture();active=notes[0]?.id;render();if(active)open(active);toast('Đã chuyển vào thùng rác (fixture)');});
$('history-button').addEventListener('click',()=>{$('history-panel').hidden=!$('history-panel').hidden;$('history-button').setAttribute('aria-expanded',String(!$('history-panel').hidden));});$('history-close').addEventListener('click',()=>$('history-panel').hidden=true);$('share-button').addEventListener('click',()=>{$('share-panel').hidden=!$('share-panel').hidden;});$('share-close').addEventListener('click',()=>$('share-panel').hidden=true);$('revoke-share').addEventListener('click',()=>{ $('share-panel').hidden=true;toast('Đã ngừng chia sẻ fixture');});$('checklist-button').addEventListener('click',()=>{const area=$('body');const at=area.selectionStart;area.setRangeText('\n☐ Mục checklist mới',at,area.selectionEnd,'end');area.dispatchEvent(new Event('input',{bubbles:true}));area.focus();});$('code-button').addEventListener('click',()=>{const area=$('body'),a=area.selectionStart,b=area.selectionEnd;area.setRangeText('\n```\nMã tổng hợp\n```\n',a,b,'end');area.dispatchEvent(new Event('input',{bubbles:true}));area.focus();});$('more-button').addEventListener('click',()=>toast('Thao tác bổ sung: ghim, xuất, xóa vĩnh viễn'));
document.querySelectorAll('[data-scenario]').forEach(button=>button.addEventListener('click',()=>{button.closest('details')?.removeAttribute('open');previewMode=button.dataset.scenario==='empty'?'empty':null;const messages={ready:['synced','Đã đồng bộ'],loading:['loading','Đang tải danh sách…'],offline:['draft','Ngoại tuyến · đã giữ trên máy'],error:['error','Lỗi đồng bộ · bản nháp vẫn được giữ'],conflict:['conflict','Xung đột phiên · bản nháp của bạn vẫn được giữ'],empty:['synced','Kho tổng hợp trống']};const [state,label]=messages[button.dataset.scenario];setState(state,label);render();}));
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search').focus();}if(e.key==='Escape'){shell.classList.remove('show-folders');if(innerWidth<=700)shell.classList.remove('editing');}});
const viewport=window.visualViewport;const updateKeyboardInset=()=>{const inset=viewport?Math.max(0,window.innerHeight-viewport.height-viewport.offsetTop):0;document.documentElement.style.setProperty('--keyboard-inset',`${Math.round(inset)}px`);if(shell.classList.contains('editing'))resizeTitle();};viewport?.addEventListener('resize',updateKeyboardInset);window.addEventListener('resize',updateKeyboardInset);for(const field of [$('title'),$('body')])field.addEventListener('focus',()=>setTimeout(()=>field.scrollIntoView({block:'nearest',behavior:'smooth'}),60));updateKeyboardInset();render();open(active);
